/* 仿QQ名片消息列表·粉by白咪饭 — nuojiji messaging app theme */

/* QQ_消息列表by白咪饭 (灵感仿照参考灿灿，感谢灿灿老师！😘) */

:root {
    /* 🌟 全局主色调换成低饱和粉色 🌟 */
    --qq-gray-blue: #f5ebed;

    --nj-msg-chat-bg: #fffcfc; /* 列表底色稍微泛一点点粉白，更柔和 */
    --nj-msg-bg: #fffcfc;
    --nj-msg-text: #000000;
    --nj-msg-text-muted: #9c8e92; /* 次要文字也带点暖调灰 */
    --nj-msg-text-time: #c5b9bc; /* 时间戳带暖调 */
    --nj-msg-unread-bg: #e6a1b2; /* 未读红点变成柔和低饱和粉 */
    --nj-msg-card-bg-pinned: var(--qq-gray-blue); 
    --nj-msg-avatar-radius: 50%;
    --nj-msg-tabbar-bg: #ffffff;
    --nj-msg-tabbar-active: #d695a7; /* 底部图标激活态换成相配的豆沙粉 */
    --nj-msg-tabbar-inactive: #5a4b4e;
    --nj-msg-tabbar-border: 1px solid #f6eff1;
}

/* 🌟 核心防抖修复 🌟 */
#messaging-chat-tab {
    overflow-x: hidden !important;
    width: 100% !important;
    max-width: 100vw !important;
}

/* ==========================================
   1. 顶栏复刻 (绝对固定 + 左侧状态切号)
========================================== */
.nj-chat-tab-header {
    background: var(--qq-gray-blue) !important; 
    border-bottom: none !important;
    box-shadow: none !important;
    height: calc(60px + var(--nuo-safe-top)) !important;
    padding: 0 !important;
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    z-index: 9999 !important;
}

.nj-chat-tab-header::before, .nj-chat-tab-header::after {
    display: none !important;
    content: '' !important;
}

/* 状态栏切号绑定：右侧靠紧返回键 */
.nj-chat-tab-header-title-btn {
    display: flex !important;
    position: absolute !important;
    left: -10px !important; 
    transform: none !important;
    top: calc(18px + var(--nuo-safe-top)) !important; 
    align-items: center !important;
    justify-content: flex-start !important; 
    color: transparent !important; 
    background: transparent !important;
    z-index: 100 !important;
    height: 24px !important;
    padding: 0 !important;
}
.nj-chat-tab-header-title-btn svg { display: none !important; }
.nj-chat-tab-header-title-btn::before { display: none !important; }

.nj-chat-tab-header-title-btn::after {
    display: block !important;
    content: '我Crush了 >' !important;
    font-size: 14px !important; 
    font-weight: 500 !important;
    color: #4a3e41 !important; /* 顶部文字也调柔和点 */
    line-height: 1 !important;
    padding-left: 20px !important; 
    background-image: url('https://i.postimg.cc/G3gkv7qx/IMG-5274.png');
    background-size: 16px 16px; 
    background-repeat: no-repeat;
    background-position: left center; 
}

/* 🟥 返回键 🟥 */
.nj-chat-tab-header-back svg { display: none !important; } 
.nj-chat-tab-header-back {
    display: block !important; 
    position: absolute !important;
    width: 24px !important; 
    height: 24px !important; 
    left: 16px !important; 
    top: calc(18px + var(--nuo-safe-top)) !important; 
    z-index: 99 !important; 
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%234a3e41" stroke-width="2"><polyline points="15 18 9 12 15 6"/></svg>'); /* 返回箭头变棕粉调 */
    background-size: contain;
    background-repeat: no-repeat;
}
.nj-chat-tab-header-back::after { content: ''; }

/* 右侧大加号 */
.nj-chat-tab-header-edit svg { display: none !important; }
.nj-chat-tab-header-edit {
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%234a3e41" stroke-width="1.5"><line x1="12" y1="4" x2="12" y2="20"/><line x1="4" y1="12" x2="20" y2="12"/></svg>'); /* 加号变棕粉调 */
    background-size: 28px;
    background-repeat: no-repeat;
    background-position: center;
    width: 32px !important;
    height: 32px !important;
    position: absolute;
    right: 16px;
    top: calc(14px + var(--nuo-safe-top));
}

/* ==========================================
   2. 顶部名片卡片
========================================== */
.nj-chat-tab-search-wrap {
    display: block !important;
    background: var(--qq-gray-blue) !important; 
    padding: 10px 16px 20px 16px !important;
    margin: 0 !important;
    margin-top: calc(60px + var(--nuo-safe-top)) !important;
    position: relative !important;
    box-sizing: border-box !important;
    width: 100% !important;
}

.nj-chat-tab-search {
    background: #ffffff !important;
    border-radius: 16px !important; 
    height: 140px !important; 
    border: none !important;
    box-shadow: 0 4px 15px rgba(220,195,200,0.15) !important; /* 阴影也带点粉粉的空气感 */
    position: relative !important;
    display: block !important;
    width: 100% !important;
    box-sizing: border-box !important;
    overflow: hidden !important;
}

.nj-chat-tab-search * {
    display: none !important;
}

/* 🌟 核心板块 1：名片左侧头像 🌟 */
.nj-chat-tab-search::before {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    left: 20px !important; 
    top: 24px !important;  
    width: 65px !important;
    height: 65px !important;
    border-radius: 50% !important;
    background-image: url('https://i.postimg.cc/yYTV3tV0/IMG-4796.jpg') !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
}

/* 🌟 核心板块 2：[你的昵称] + [无缝跟随图片的绝密配方] 🌟 */
.nj-chat-tab-search::after {
    content: ' MiMi' !important; 
    position: absolute !important;
    left: 100px !important; 
    top: 24px !important;   
    font-size: 18px !important;  
    font-weight: 500 !important; 
    color: #4a3e41 !important; /* 昵称变柔和 */  

    width: auto !important; 
    padding-right: 25px !important; 

    background-image: url('https://i.postimg.cc/G3gkv7qx/IMG-5274.png') !important;
    background-repeat: no-repeat !important;
    background-position: right calc(50% + -1px) !important; 
    background-size: 20px 20px !important; 
}

/* 🌟 核心板块 3：[个性签名] 🌟 */
.nj-chat-tab-search-wrap::before {
    content: '世界太宏大了，我们都不要走进悲伤里' !important;
    position: absolute !important;
    z-index: 10 !important;
    left: 115px !important; 
    top: 80px !important;   
