:root {
  /* ---- 全局极透壁纸强锁 ---- */
  --chat-bg-image: url('https://i.postimg.cc/bYTXRxFK/1040g3k831m9rj14dksdg5phb0pdguafeo1tdf90.jpg') !important;
  --chat-bg-color: transparent !important; 
  --chat-bg-size: cover !important;
  --chat-bg-position: center !important;

  /* ---- 顶栏：无影高磨霜玻 ---- */
  --chat-header-bg: rgba(255, 255, 255, 0.12);
  --chat-header-blur: 26px;
  --chat-header-border: rgba(255, 255, 255, 0.28);

  /* ---- 气泡：单晶极滑剔透风 ---- */
  --bubble-me-bg: rgba(255, 255, 255, 0.24);
  --bubble-me-border: 1px solid rgba(255, 255, 255, 0.52);
  --bubble-me-shadow: 0 4px 18px rgba(0, 0, 0, 0.05), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  --bubble-me-backdrop: blur(20px) saturate(155%);
  --bubble-me-radius: 20px;
  --bubble-me-radius-first: 20px 20px 4px 20px;
  --bubble-me-radius-mid: 20px 4px 4px 20px;
  --bubble-me-radius-last: 20px 4px 20px 20px;

  --bubble-them-bg: rgba(255, 255, 255, 0.16);
  --bubble-them-border: 1px solid rgba(255, 255, 255, 0.42);
  --bubble-them-shadow: 0 4px 18px rgba(0, 0, 0, 0.04), inset 0 1px 0 rgba(255, 255, 255, 0.6);
  --bubble-them-backdrop: blur(20px) saturate(155%);
  --bubble-them-radius: 20px;
  --bubble-them-radius-first: 20px 20px 20px 4px;
  --bubble-them-radius-mid: 4px 20px 20px 4px;
  --bubble-them-radius-last: 4px 20px 20px 20px;

  /* ---- 底部发图打文字：幽蓝浅凉空岛 ---- */
  --input-area-bg: rgba(255, 255, 255, 0.14);
  --input-area-blur: 26px;
  --input-area-border-top: 1px solid rgba(255, 255, 255, 0.28);
  --input-box-bg: rgba(255, 255, 255, 0.26);
  --input-box-border: 1px solid rgba(255, 255, 255, 0.48);
  --input-box-radius: 22px;
  --input-box-blur: blur(14px);

  --translation-bg: transparent;
  --translation-border: none;
  --translation-shadow: none;
  --scrollbar-width: 0px;
}

/* ================================================
   0. 大破重晦，破净全局内藏灰影地砖！
================================================ */
html, body, #root, .chat-detail-screen, #chat-detail-screen {
  background-image: url('https://i.postimg.cc/bYTXRxFK/1040g3k831m9rj14dksdg5phb0pdguafeo1tdf90.jpg') !important;
  background-size: cover !important; background-position: center !important;
  background-repeat: no-repeat !important; background-color: #d8e3ed !important;
  background-attachment: fixed !important; position: relative !important;
}
.chat-messages-area, .chat-message-list-custom, .chat-bg-layer, [class*="main-bg"] {
  background: transparent !important; background-color: transparent !important;
}

/* ================================================
   1. 【诗意进化的灵魂】已读与发送完全退行变赋
================================================ */
/* 把原本生平朴无华的 18:30 已读/已发送 字块剥零再充植！ */
.msg-status-custom.is-read, 
[class*="msg-status"].is-read, 
[class*="status"].is-read,
.msg-wa-checks.read {
  font-size: 0 !important; /* 隐藏古语 */
}
.msg-status-custom.is-read::after, 
[class*="msg-status"].is-read::after, 
[class*="status"].is-read::after,
.msg-wa-checks.read::after {
  content: "喧闹的喜宴" !important;
  font-size: 11px !important;
  letter-spacing: 0.8px !important;
  font-weight: 500 !important;
  color: rgba(30, 50, 80, 0.95) !important;
  text-shadow: 0 0 6px rgba(255, 255, 255, 0.8) !important;
}

/* 凡未读既过往之行 -> 幻归回首那日 */
.msg-status-custom.is-sent, 
.msg-status-custom:not(.is-read), 
[class*="msg-status"].is-sent, 
[class*="status"].is-sent {
  font-size: 0 !important;
}
.msg-status-custom.is-sent::after, 
.msg-status-custom:not(.is-read)::after, 
[class*="msg-status"].is-sent::after, 
[class*="status"].is-sent::after {
  content: "回想那一天" !important;
  font-size: 11px !important;
  letter-spacing: 0.8px !important;
  font-weight: 400 !important;
  color: rgba(60, 75, 100, 0.65) !important;
}

/* ================================================
   2. 顶栏：除尽圆头，真正在水面平齐直向死居
================================================ */
.header-avatar-container, .chat-header-avatar, .header-profile-section img { display: none !important; }
.chat-header-custom {
  position: relative !important;
  display: flex !important; align-items: center !important; justify-content: center !important; min-height: 56px !important;
}
.header-profile-section {
  position: absolute !important;
  left: 50% !important; bottom: 15px !important; /* 精确齐贴，和雨伞处在一个高线上 */
  transform: translateX(-50%) !important;
  display: flex !important; flex-direction: column !important; align-items: center !important; justify-content: center !important; pointer-events: none !important;
}
.chat-header-title { text-align: center !important; margin: 0 !important; font-size: 16px !important; color: rgba(30, 40, 55, 0.92) !important; }
.chat-header-subtitle { text-align: center !important; margin: 0 !important; }

/* ================================================
   3. UI 彻底演替： 1:1无缺清锋线条雨伞 (.gg-umbrella)
================================================ */
.header-btn-back svg, .header-btn-phone svg, .header-btn-video svg, .header-btn-info svg,
.input-btn-plus svg, .input-btn-ai svg, .input-btn-mic svg, .input-btn-sticker svg,
.send-btn-custom svg, .more-options-item-row svg { display: none !important; }

.header-btn-back, .header-btn-phone, .header-btn-video, .header-btn-info,
.input-btn-plus, .input-btn-ai, .input-btn-mic, .input-btn-sticker,
.send-btn-custom, .more-options-item-row {
  position: relative !important; display: flex !important; align-items: center !important; justify-content: center !important; min-width: 26px !important; min-height: 26px !important; overflow: visible !important;
}

.header-btn-back::before, .header-btn-phone::before, .header-btn-video::before, .header-btn-info::before,
.input-btn-plus::before, .input-btn-ai::before, .input-btn-mic::before, .input-btn-sticker::before,
.send-btn-custom::before, .more-options-item-row::before {
  content: "" !important; display: inline-block !important;
  width: 22px !important; height: 22px !important; min-width: 22px !important; min-height: 22px !important;
  background-color: currentColor !important;
  -webkit-mask-image: url("data:image/svg+xml;charset=utf-8,%3Csvg viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M4 12 C4 3 20 3 20 12 Z' /%3E%3Cpath d='M12 12 L12 18' /%3E%3Cpath d='M12 18 C12 21.5 6 21.5 6 18' /%3E%3C/svg%3E") !important;
  -webkit-mask-size: contain !important; -webkit-mask-repeat: no-repeat !important; -webkit-mask-position: center !important;
}
.more-options-item-row { gap: 12px !important; }

/* ================================================
