/* ================================================
   5. 单气泡严禁分合双层
================================================ */
.bubble-me-custom::before, .bubble-me-custom::after, .bubble-them-custom::before, .bubble-them-custom::after,
.bubble-deco-me::before, .bubble-deco-me::after, .bubble-deco-them::before, .bubble-deco-them::after { display: none !important; }

/* ================================================
   6. 雷达杀器：若为图或通资转赐 坚删气泡壳
================================================ */
.bubble-me-custom:has(img), .bubble-them-custom:has(img),
.bubble-me-custom:has([class*="sticker"]), .bubble-them-custom:has([class*="sticker"]),
.bubble-me-custom:has([class*="meme"]), .bubble-them-custom:has([class*="meme"]),
.bubble-me-custom:has([class*="emoji"]), .bubble-them-custom:has([class*="emoji"]),
.bubble-me-custom:has(.msg-transfer-card), .bubble-them-custom:has(.msg-transfer-card),
.bubble-me-custom:has([class*="call"]), .bubble-them-custom:has([class*="call"]) {
  background: transparent !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important;
  border: none !important; box-shadow: none !important; padding: 0 !important;
}
[class*="sticker"], [class*="meme"], [class*="emoji"] {
  background: transparent !important; backdrop-filter: none !important; border: none !important; box-shadow: none !important;
}

/* ================================================
   7. 【终极超薄矮化】Apple Music 音轨舱 & .gg-cloud 云朵
   不仅保留苹果宽调式舒展宽(230px)，纵度狂切成一张卡信薄纸！
================================================ */
.msg-transfer-card .msg-transfer-status-text,
.msg-transfer-card [class*="status"],
.msg-transfer-card [class*="subtitle"]:nth-of-type(n+3) { display: none !important; }

.msg-transfer-card {
  background: rgba(255, 255, 255, 0.22) !important;
  backdrop-filter: blur(32px) saturate(180%) !important; -webkit-backdrop-filter: blur(32px) saturate(180%) !important;
  border: 1px solid rgba(255, 255, 255, 0.58) !important;
  border-radius: 16px !important; 
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.05), inset 0 1px 0 rgba(255, 255, 255, 0.85) !important;

  /* [极矮之密] 上下大砍仅留 5px/14px，视觉薄如纸！ */
  padding: 5px 14px 14px 10px !important; 
  min-width: 220px !important;
  max-width: 250px !important; 

  display: flex !important; align-items: center !important;
  position: relative !important; overflow: hidden !important;
}

.msg-transfer-card > div:not(.transfer-icon-container):not([class*="icon"]) {
  display: flex !important; flex-direction: column !important; justify-content: center !important; flex: 1 !important; overflow: hidden !important;
}

.msg-transfer-card .msg-transfer-amount, .msg-transfer-card [class*="amount"] {
  font-weight: 700 !important; font-size: 15px !important; color: rgba(20, 30, 45, 0.94) !important;
  white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important;
  line-height: 1.1 !important; margin-bottom: 1px !important; text-shadow: 0 1px 1px rgba(255, 255, 255, 0.7) !important;
}
.msg-transfer-card .msg-transfer-label, .msg-transfer-card [class*="label"] {
  font-size: 10px !important; color: rgba(55, 70, 90, 0.75) !important;
  white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important;
  line-height: 1 !important; margin: 0 !important; text-transform: uppercase !important;
}

/* ------ .gg-cloud 云朵免溢死缩高清植入 ------ */
.msg-transfer-card svg, .msg-transfer-card img { display: none !important; }

.transfer-icon-container, .msg-transfer-card [class*="icon"] {
  width: 26px !important; height: 26px !important; /* 从32px再瘦向26px */
  margin-right: 10px !important;
  background: rgba(255, 255, 255, 0.3) !important; border: 1px solid rgba(255, 255, 255, 0.65) !important;
  box-shadow: 0 2px 6px rgba(0,0,0,0.04) !important; border-radius: 50% !important;
  display: flex !important; align-items: center !important; justify-content: center !important; position: relative !important; overflow: visible !important; 
}

.transfer-icon-container::before, .msg-transfer-card [class*="icon"]::before {
  content: "" !important; display: inline-block !important; width: 15px !important; height: 15px !important;
  background-color: rgba(30, 45, 65, 0.82) !important;
  -webkit-mask-image: url("data:image/svg+xml;charset=utf-8,%3Csvg viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z'/%3E%3C/svg%3E") !important;
  -webkit-mask-size: contain !important; -webkit-mask-repeat: no-repeat !important; -webkit-mask-position: center !important;
}
.transfer-icon-container::after, .msg-transfer-card [class*="icon"]::after { display: none !important; }

/* 极低压底进度细滑轨 */
.msg-transfer-card::after {
  content: "" !important; position: absolute !important; 
  bottom: 4px !important; left: 14px !important; right: 14px !important; height: 1.5px !important;
  border-radius: 99px !important;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.95) 0%, rgba(255, 255, 255, 0.9) 65%, rgba(255, 255, 255, 0.22) 65%, rgba(255, 255, 255, 0.22) 100%) !important;
  pointer-events: none !important;
}

/* ================================================
   8. 翻译 & 引用轻敏散水滴舱 (恪守源字正绿本心)
================================================ */
.msg-translation-wrapper { display: block !important; }
.msg-translation-content { display: none !important; }
.msg-translation-detached { display: block !important; margin-top: 6px !important; }
.msg-translation-detached-content {
  background: rgba(255, 255, 255, 0.22) !important; backdrop-filter: blur(20px) saturate(150%) !important;
  border: 1px solid rgba(255, 255, 255, 0.5) !important; border-radius: 14px !important; padding: 8px 12px !important;
}
.msg-reply-block { display: none !important; }
.msg-reply-block-detached {
  display: flex !important; margin-bottom: 5px !important; background: rgba(255, 255, 255, 0.16) !important;
  backdrop-filter: blur(16px) saturate(150%) !important; border: 1px solid rgba(255, 255, 255, 0.45) !important;
  border-radius: 12px !important; padding: 7px 12px !important;
}

/* ================================================
   9. 照片平稳手拨
================================================ */
.msg-image-wrapper {
  background: transparent !important; border: none !important; box-shadow: none !important;
  display: flex !important; flex-direction: row !important; gap: 6px !important; overflow-x: auto !important; max-width: 240px !important; scrollbar-width: none !important;
}
.msg-image-wrapper::-webkit-scrollbar { display: none !important; }
.msg-image-wrapper img { border-radius: 16px !important; width: 180px !important; height: 180px !important; object-fit: cover !important; flex-shrink: 0 !important; }
.msg-image-wrapper img:only-child { width: 200px !important; height: 200px !important; }
